import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)):
        return -1.0
    L = np.convolve(h, h)
    Lp = np.concatenate(([0.0], L, [0.0]))
    a = Lp[:-1]
    b = Lp[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = Lp.max()
    l1 = s * s
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def _resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(N + 1) * (M / N)
    out = np.empty(N)
    for k in range(N):
        lo = edges[k]; hi = edges[k + 1]
        ilo = int(np.floor(lo)); ihi = int(np.floor(hi))
        if ihi >= M:
            ihi = M - 1; hi = float(M)
        if ilo == ihi:
            out[k] = h[ilo] * (hi - lo)
        else:
            val = h[ilo] * (ilo + 1 - lo)
            if ihi > ilo + 1:
                val += cum[ihi] - cum[ilo + 1]
            val += h[ihi] * (hi - ihi)
            out[k] = val
        out[k] /= (hi - lo)
    return out


def _make(N, c, beta):
    i = np.arange(N, dtype=float)
    x = (i + 0.5) / N
    return (x + c) ** (-0.5) * (1.0 - x) ** beta


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def ot():
        return time.process_time() > deadline

    # Seed candidate
    if start is not None and np.asarray(start).size > 0:
        base = np.maximum(np.asarray(start, dtype=float), 0.0)
        best_h = base.copy()
        best_R = _R(base)
    else:
        best_h = _make(2000, 0.0, 0.05)
        best_R = _R(best_h)

    # Try analytic family too, keep whichever is better
    for c in [0.0, 1e-4, 1e-3]:
        for beta in [0.0, 0.05, 0.1]:
            if ot():
                break
            h = _make(2000, c, beta)
            r = _R(h)
            if r > best_R:
                best_R = r; best_h = h

    print("seed R=%.6f N=%d" % (best_R, best_h.size))

    # Coordinate ascent in log space at increasing resolution
    scales = [best_h.size]
    for N in [1000, 2000, 4000, 8000]:
        if N > best_h.size:
            scales.append(N)
    # ensure we also try downscaling for speed if start is huge
    if best_h.size > 8000:
        scales = [2000, 4000, 8000]

    for N in scales:
        if ot():
            break
        h = _resample(best_h, N)
        R = _R(h)
        if R > best_R:
            best_R = R; best_h = h.copy()
        delta = 0.15
        for sweep in range(20):
            if ot():
                break
            improved = False
            order = np.arange(N)
            # try perturbing all coords at once first (cheap direction probe)
            for idx in order:
                if ot():
                    break
                bv = h[idx]
                if bv <= 0:
                    continue
                cur = _R(h)
                h[idx] = bv * np.exp(delta)
                Rp = _R(h)
                h[idx] = bv * np.exp(-delta)
                Rm = _R(h)
                if Rp >= Rm and Rp > cur:
                    h[idx] = bv * np.exp(delta); improved = True
                elif Rm > cur:
                    h[idx] = bv * np.exp(-delta); improved = True
                else:
                    h[idx] = bv
            Rnew = _R(h)
            if Rnew > best_R:
                best_R = Rnew; best_h = h.copy()
            delta *= 0.6
            if not improved and delta < 1e-4:
                break
        print("N=%d R=%.6f best=%.6f" % (N, _R(h), best_R))

    # Differential evolution style random perturbation polish on best
    rng = np.random.default_rng(12345)
    h = best_h.copy()
    N = h.size
    sigma = 0.05
    while not ot():
        cand = h * np.exp(rng.normal(0, sigma, size=N))
        r = _R(cand)
        if r > best_R:
            best_R = r; best_h = cand.copy(); h = cand
            sigma = min(sigma * 1.05, 0.2)
        else:
            sigma *= 0.999
            if sigma < 1e-3:
                sigma = 0.02

    print("Best: R=%.6f N=%d" % (best_R, best_h.size))
    return np.asarray(best_h, dtype=float)
